Item.method_code:
Innovator inn = this.getInnovator();
//引数（遷移先はハードコーディング）
Item callMethod = inn.newItem("method","h4_Promote_WFGroup_ApTarget");
string id = this.getID();
callMethod.setProperty("destination", "Approved");
callMethod.setProperty("sourceId", id);
//プロモートメソッド呼び出し
callMethod =callMethod.apply();
if(callMethod.isError())
{
    return inn.newError(callMethod.getErrorString());   
}

// 承認者と承認日時の記載
Item callMethod2 = inn.newItem("method","h4_Set_ApprovalInfo_For_ApWFG");
callMethod2.setProperty("id", id);
callMethod2 = callMethod2.apply();
if(callMethod2.isError())
{
    return inn.newError(callMethod2.getErrorString());   
}

return this;
